(5547521, 800609, 66515, '<td valign="top">Some really strange artifacts in the sky from your processing.</td>', 'Some really strange artifacts in the sky from your processing.', '2009-06-27 18:42:26.000000', NULL, 1),
(5547523, 801651, 66515, '<td valign="top">simple subject. Composition is okay but something is a little off with it. Its not quite at an oblique from the side. Its not quite vertical. Neither are deliberate so I think it hurts the shot.</td>', 'simple subject. Composition is okay but something is a little off with it. Its not quite at an oblique from the side. Its not quite vertical. Neither are deliberate so I think it hurts the shot.', '2009-06-27 18:43:52.000000', NULL, 1),
(5547525, 800388, 66515, '<td valign="top">well...we have the ground part and now we need to go up! Unique idea though. I think the pot/vase on the left needs to be taken out as it isn''t helping the scene at all.</td>', 'well...we have the ground part and now we need to go up! Unique idea though. I think the pot/vase on the left needs to be taken out as it isn''t helping the scene at all.', '2009-06-27 18:44:58.000000', NULL, 1),
(5547528, 801166, 66515, '<td valign="top">great shot for the challenge but I am not a fan of the border. It really seems to suck a lot of the color from the image.</td>', 'great shot for the challenge but I am not a fan of the border. It really seems to suck a lot of the color from the image.', '2009-06-27 18:45:47.000000', NULL, 1),
(5547530, 801241, 66515, '<td valign="top">the perspective works perfectly for the challenge. Unfortunately detail in the clouds are blown out.  Exposing for the sky and then using fill flash for the horse''s face might have worked here.</td>', 'the perspective works perfectly for the challenge. Unfortunately detail in the clouds are blown out.  Exposing for the sky and then using fill flash for the horse''s face might have worked here.', '2009-06-27 18:46:51.000000', NULL, 1),
(5547534, 801270, 66515, '<td valign="top">great persective but the upper part of the image is really over exposed. This really needed to be shot at a different time of day because this scene has so much potential if shot in good light.</td>', 'great persective but the upper part of the image is really over exposed. This really needed to be shot at a different time of day because this scene has so much potential if shot in good light.', '2009-06-27 18:50:58.000000', NULL, 1),
(5547536, 801620, 66515, '<td valign="top">I see this shot has been validated and I figured it was legit when I first saw it. I still want to know how it was done. :)</td>', 'I see this shot has been validated and I figured it was legit when I first saw it. I still want to know how it was done. :)', '2009-06-27 18:52:58.000000', NULL, 1),
(5547573, 801698, 72928, '<td valign="top">The shot is a little dark, A little more daylight would defenitely render a beeter image</td>', 'The shot is a little dark, A little more daylight would defenitely render a beeter image', '2009-06-27 19:36:36.000000', NULL, 1),
(5547595, 801664, 43774, '<td valign="top">This is gorgeous!! It''s like a rainshower of crystals, great job! My only nit-pick is that the colour is sort of blah. I''m very early in the voting yet, so I''ll give this an 8 for now and come back to it later.</td>', 'This is gorgeous!! It''s like a rainshower of crystals, great job! My only nit-pick is that the colour is sort of blah. I''m very early in the voting yet, so I''ll give this an 8 for now and come back to it later.', '2009-06-27 19:50:57.000000', NULL, 1),
(5547597, 801437, 43774, '<td valign="top">Gorgeous! Freaky looking trees too.</td>', 'Gorgeous! Freaky looking trees too.', '2009-06-27 19:51:01.000000', NULL, 1),
(5547668, 800397, 72928, '<td valign="top">nice title!, it would have been nice to have the fountain getting sunlight too, it would have made the water more attractive</td>', 'nice title!, it would have been nice to have the fountain getting sunlight too, it would have made the water more attractive', '2009-06-27 20:22:39.000000', NULL, 1);
