(5550149, 801166, 90754, '<td valign="top">I''m not a fan of the border but I did not take that into account with my voting.  I love the perspective on this and the color of the tree with the greenery.</td>', 'I''m not a fan of the border but I did not take that into account with my voting.  I love the perspective on this and the color of the tree with the greenery.', '2009-06-29 21:34:41.000000', NULL, 1),
(5550151, 801340, 90754, '<td valign="top">Perfect spacing/comp.  I love the detail of the wings and the loss of detail between wings and body.</td>', 'Perfect spacing/comp.  I love the detail of the wings and the loss of detail between wings and body.', '2009-06-29 21:35:22.000000', NULL, 1),
(5550152, 800131, 90754, '<td valign="top">Very interesting.  I like the sparkle the light adds to this.</td>', 'Very interesting.  I like the sparkle the light adds to this.', '2009-06-29 21:35:45.000000', NULL, 1),
(5550153, 801653, 90754, '<td valign="top">Great expression.  Love the lean of the head and the angle of the capture.  The colors are beautiful.</td>', 'Great expression.  Love the lean of the head and the angle of the capture.  The colors are beautiful.', '2009-06-29 21:36:07.000000', NULL, 1),
(5550154, 800636, 90754, '<td valign="top">Fantastic feathers.  Looks almost like a flying skeleton in a way.  Love it.  I even like the comp even though free space is the opposite direction the bird is facing.. Sort of like it is springing forth from the free space into whatever lies beyond.</td>', 'Fantastic feathers.  Looks almost like a flying skeleton in a way.  Love it.  I even like the comp even though free space is the opposite direction the bird is facing.. Sort of like it is springing forth from the free space into whatever lies beyond.', '2009-06-29 21:36:59.000000', NULL, 1),
(5550155, 801620, 90754, '<td valign="top">Very cool.  I''d love to know how you did this in basic.</td>', 'Very cool.  I''d love to know how you did this in basic.', '2009-06-29 21:37:18.000000', NULL, 1),
(5550156, 801529, 90754, '<td valign="top">Good color.  I like the title with the image.  Wish it was all in focus.</td>', 'Good color.  I like the title with the image.  Wish it was all in focus.', '2009-06-29 21:37:54.000000', NULL, 1),
(5550157, 800112, 90754, '<td valign="top">Great comp.  Love the colors too.  Wish the foreground grass was smaller and not as distracting but I like it in the shot.</td>', 'Great comp.  Love the colors too.  Wish the foreground grass was smaller and not as distracting but I like it in the shot.', '2009-06-29 21:38:21.000000', NULL, 1),
(5550158, 800866, 90754, '<td valign="top">Hilarious title.  Great perspective.  I love that the green frames this.  I find the flare distracting but it isn''t overly distracting.</td>', 'Hilarious title.  Great perspective.  I love that the green frames this.  I find the flare distracting but it isn''t overly distracting.', '2009-06-29 21:38:53.000000', NULL, 1),
(5550160, 800828, 90754, '<td valign="top">This looks like a very cool statue.  I also like the wave of the reflection in the glass.  The colors are a little flat to me though.</td>', 'This looks like a very cool statue.  I also like the wave of the reflection in the glass.  The colors are a little flat to me though.', '2009-06-29 21:39:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5550163, 801319, 90754, '<td valign="top">Great expression.  The legs being out of focus is distracting.  Color is good.</td>', 'Great expression.  The legs being out of focus is distracting.  Color is good.', '2009-06-29 21:43:16.000000', NULL, 1),
(5550164, 801697, 90754, '<td valign="top">Love this perspective.  So cute!</td>', 'Love this perspective.  So cute!', '2009-06-29 21:43:27.000000', NULL, 1),
(5550165, 801619, 90754, '<td valign="top">Cool stairs.  I like the black and white.</td>', 'Cool stairs.  I like the black and white.', '2009-06-29 21:44:04.000000', NULL, 1),
(5550166, 801588, 90754, '<td valign="top">What a great capture.  It''s a little dark for me but I like the colors and crop.</td>', 'What a great capture.  It''s a little dark for me but I like the colors and crop.', '2009-06-29 21:44:34.000000', NULL, 1),
(5550169, 801302, 90754, '<td valign="top">Such interesting colors.  I like the gold mixed with the purple and black.  I also like the crop of the propeller.</td>', 'Such interesting colors.  I like the gold mixed with the purple and black.  I also like the crop of the propeller.', '2009-06-29 21:45:38.000000', NULL, 1),
(5550170, 801736, 90754, '<td valign="top">Very beautiful.  Great balance.</td>', 'Very beautiful.  Great balance.', '2009-06-29 21:45:57.000000', NULL, 1),
(5550171, 801666, 90754, '<td valign="top">I love the detail in this photo.</td>', 'I love the detail in this photo.', '2009-06-29 21:46:28.000000', NULL, 1),
(5550173, 801441, 90754, '<td valign="top">I love the top of this photo.  Hard to explain.  I like the lines and how they move towards the light and I like the color at the top. I wish the opening at the top was bigger but that''s just nitpicking.</td>', 'I love the top of this photo.  Hard to explain.  I like the lines and how they move towards the light and I like the color at the top. I wish the opening at the top was bigger but that''s just nitpicking.', '2009-06-29 21:47:21.000000', NULL, 1),
